using Seamless.Management;
using Seamless.Management.Server;

namespace Management.Tests;

[Collection("AuditStorage")]
public sealed class NativeUpdateAudit{
    private static string Root()=>Path.Combine(Environment.GetEnvironmentVariable("SEAMLESS_MANAGEMENT_TEST_ROOT")??throw new InvalidOperationException("Missing isolated root."),Guid.NewGuid().ToString("N"));
    private static Definition Update(string id="insert",int key=1)=>new(id,"Native",DefinitionKind.Query,"Model.Updates","Run",new("1",[new("Update.cs","using Seamless.Management.Server;namespace Model;public static class Updates{public static int Run(ManagementExecutionContext context){context.GetDatabase<Db>().Rows.Add(new Records.Row("+key+",9));return 9;}}")],[]),true);
    private static ExecuteRequest Request(string id)=>new(id,null,ManagementJson.Element(new{}));
    private static Definition Count()=>new("count","Native",DefinitionKind.Query,"Model.Counts","Run",new("1",[new("Count.cs","using System.Linq;using Seamless.Management.Server;namespace Model;public static class Counts{public static int Run(ManagementExecutionContext context)=>context.GetDatabase<Db>().Rows.Count();}")],[]));
    private static UserAccount Login(Seamless.Management.Server.ManagementService service)=>service.Authenticate(service.Login(new("admin","TestPassword-123")).Token);
    private static async Task Until(Func<bool> condition){using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(30));while(!condition()){await Task.Delay(30,timeout.Token);}}
    [Fact]public async Task PublishedUpdateCommitsToItsWalAndTransfersInTheBackground(){
        using var store=ManagementStore.Initialize(Root(),"admin","TestPassword-123");using var service=new Seamless.Management.Server.ManagementService(store){AuditDeliveryPaused=true};var user=Login(service);NativeWorkflow.Publish(service,user,NativeWorkflow.Database());NativeWorkflow.Publish(service,user,Update());Assert.Equal(9,Assert.Single(service.Execute(user,Request("insert"),CancellationToken.None)).Value.GetInt32());
        var origin=Assert.Single(store.List<AuditOrigin>("auditOrigin").Items);Assert.Equal("audit-v1",origin.Options.MetadataConsumer);Assert.Empty(store.AuditEvents(new(Action:AuditAction.DataChange)).Items);service.AuditDeliveryPaused=false;await Until(()=>store.AuditEvents(new(Action:AuditAction.DataChange)).Items.Length==1);
        var item=Assert.Single(store.AuditEvents(new(Text:"Model.Updates.Run",Action:AuditAction.DataChange)).Items);Assert.Equal(origin.Database,item.Database);Assert.Equal("ADMIN",item.SubjectId);Assert.Equal(store.InstanceId,item.AuthorityId);Assert.Null(item.PolicyVersion);Assert.NotNull(item.TransactionId);Assert.Equal(service.GetDefinition(user,"insert").ArtifactHash,item.CodeVersion);
    }
    [Fact]public async Task RestartFindsUnprojectedWritesWithoutRunningAnotherQuery(){
        var root=Root();using(var store=ManagementStore.Initialize(root,"admin","TestPassword-123"))using(var service=new Seamless.Management.Server.ManagementService(store){AuditDeliveryPaused=true}){var user=Login(service);NativeWorkflow.Publish(service,user,NativeWorkflow.Database());NativeWorkflow.Publish(service,user,Update());_=service.Execute(user,Request("insert"),CancellationToken.None).ToArray();Assert.Empty(store.AuditEvents(new(Action:AuditAction.DataChange)).Items);}
        using var reopened=new ManagementStore(root);Assert.Single(reopened.List<AuditOrigin>("auditOrigin").Items);using var restarted=new Seamless.Management.Server.ManagementService(reopened);await Until(()=>reopened.AuditEvents(new(Action:AuditAction.DataChange)).Items.Length==1);Assert.Single(reopened.AuditEvents(new(Action:AuditAction.DataChange)).Items);
    }
    [Fact]public async Task SchemaReplacementDoesNotLoseTheOldGenerationsPendingAudit(){
        using var store=ManagementStore.Initialize(Root(),"admin","TestPassword-123");using var service=new Seamless.Management.Server.ManagementService(store){AuditDeliveryPaused=true};var user=Login(service);NativeWorkflow.Publish(service,user,NativeWorkflow.Database());NativeWorkflow.Publish(service,user,Update());_=service.Execute(user,Request("insert"),CancellationToken.None).ToArray();var before=Assert.Single(store.List<AuditOrigin>("auditOrigin").Items);
        var next=NativeWorkflow.Database() with{Source=NativeWorkflow.Database().Source with{Revision="2"}};NativeWorkflow.Publish(service,user,next,1,1);NativeWorkflow.Publish(service,user,Update("second",2));_=service.Execute(user,Request("second"),CancellationToken.None).ToArray();service.AuditDeliveryPaused=false;await Until(()=>store.AuditEvents(new(Action:AuditAction.DataChange)).Items.Length==2);Assert.Equal(2,store.List<AuditOrigin>("auditOrigin").Items.Length);await Until(()=>store.Read<AuditOrigin>("auditOrigin",before.WalId.ToString("N"))!.Drained);
    }
    [Fact]public async Task FailedUpdateAndAbandonedEnumerationDoNotEmitSuccessfulUpdateEvents(){
        using var store=ManagementStore.Initialize(Root(),"admin","TestPassword-123");using var service=new Seamless.Management.Server.ManagementService(store){AuditDeliveryPaused=true};var user=Login(service);NativeWorkflow.Publish(service,user,NativeWorkflow.Database());var failure=Update() with{Source=Update().Source with{Files=[new("Update.cs","using Seamless.Management.Server;namespace Model;public static class Updates{public static int Run(ManagementExecutionContext context){context.GetDatabase<Db>().Rows.Add(new Records.Row(1,9));throw new System.InvalidOperationException(\"PRIVATE_FAILURE\");}}") ]}};NativeWorkflow.Publish(service,user,failure);Assert.ThrowsAny<Exception>(()=>service.Execute(user,Request("insert"),CancellationToken.None).ToArray());
        var enumeration=new Definition("enumerate","Native",DefinitionKind.Query,"Model.Updates","Run",new("1",[new("Update.cs","using System.Collections.Generic;using Seamless.Management.Server;namespace Model;public static class Updates{public static IEnumerable<int> Run(ManagementExecutionContext context){context.GetDatabase<Db>().Rows.Add(new Records.Row(2,9));yield return 1;yield return 2;}}")],[]),true);NativeWorkflow.Publish(service,user,enumeration);using(var iterator=service.Execute(user,Request("enumerate"),CancellationToken.None).GetEnumerator()){Assert.True(iterator.MoveNext());}
        await service.DrainAuditOnceAsync();Assert.Empty(store.AuditEvents(new(Action:AuditAction.DataChange,Outcome:AuditOutcome.Succeeded)).Items);Assert.Single(store.List<AuditOrigin>("auditOrigin").Items);
    }
    [Fact]public async Task ProjectionFailureKeepsTheCommittedDataAndCanBeReplayedAfterRepair(){
        using var store=ManagementStore.Initialize(Root(),"admin","TestPassword-123");using var service=new Seamless.Management.Server.ManagementService(store){AuditDeliveryPaused=true};var user=Login(service);NativeWorkflow.Publish(service,user,NativeWorkflow.Database());NativeWorkflow.Publish(service,user,Update());NativeWorkflow.Publish(service,user,Count());_=service.Execute(user,Request("insert"),CancellationToken.None).ToArray();var origin=Assert.Single(store.List<AuditOrigin>("auditOrigin").Items);
        store.Write(()=>store.Put("auditOrigin",origin.WalId.ToString("N"),origin with{ArtifactHash=new string('0',64)}));await service.DrainAuditOnceAsync();var status=Assert.Single(service.AuditDeliveryStatus(user).Items);Assert.Equal("Integrity",status.ErrorCode);Assert.False(status.Drained);Assert.Equal(1,Assert.Single(service.Execute(user,Request("count"),CancellationToken.None)).Value.GetInt32());Assert.Empty(store.AuditEvents(new(Action:AuditAction.DataChange)).Items);
        store.Write(()=>store.Put("auditOrigin",origin.WalId.ToString("N"),origin));await service.DrainAuditOnceAsync();Assert.Single(store.AuditEvents(new(Action:AuditAction.DataChange)).Items);var repaired=Assert.Single(service.AuditDeliveryStatus(user).Items);Assert.Null(repaired.ErrorCode);Assert.Equal(repaired.DurableLsn,repaired.AcknowledgedLsn);Assert.True(repaired.AcknowledgedLsn>0);
        Assert.Equal("Permission",Assert.Throws<ManagementException>(()=>service.AuditDeliveryStatus(new("viewer","",[new("*",ManagementPermission.View)]))).Code);
    }
    [Fact]public async Task PublishedGenerationIsReopenedAfterTheCommitResponseWasLost(){
        var root=Root();using(var store=ManagementStore.Initialize(root,"admin","TestPassword-123"))using(var service=new Seamless.Management.Server.ManagementService(store){AuditDeliveryPaused=true}){var user=Login(service);NativeWorkflow.Publish(service,user,NativeWorkflow.Database());NativeWorkflow.Publish(service,user,Update());NativeWorkflow.Publish(service,user,Count());_=service.Execute(user,Request("insert"),CancellationToken.None).ToArray();service.PublicationCheckpoint=(phase,_)=>{if(phase=="Committed"){throw new IOException("injected response loss");}};var next=NativeWorkflow.Database() with{Source=NativeWorkflow.Database().Source with{Revision="2"}};NativeWorkflow.Publish(service,user,next,1,1);service.PublicationCheckpoint=null;NativeWorkflow.Publish(service,user,Update("second",2));_=service.Execute(user,Request("second"),CancellationToken.None).ToArray();}
        using var reopened=new ManagementStore(root);using var restarted=new Seamless.Management.Server.ManagementService(reopened);var actor=Login(restarted);Assert.Equal(2,Assert.Single(restarted.Execute(actor,Request("count"),CancellationToken.None)).Value.GetInt32());await Until(()=>reopened.AuditEvents(new(Action:AuditAction.DataChange)).Items.Length==2);
    }
    [Fact]public void UpgradingTheSystemTablesDoesNotConvertAnExistingUserWal(){
        var root=Root();using(var legacy=ManagementStore.InitializeLegacy(root,"admin","TestPassword-123"))using(var service=new Seamless.Management.Server.ManagementService(legacy)){var user=Login(service);NativeWorkflow.Publish(service,user,NativeWorkflow.Database());NativeWorkflow.Publish(service,user,Update());}
        ManagementStoreUpgrade.Upgrade(root,root+"-backup");using var store=new ManagementStore(root);using var current=new Seamless.Management.Server.ManagementService(store);var actor=Login(current);Assert.Equal(9,Assert.Single(current.Execute(actor,Request("insert"),CancellationToken.None)).Value.GetInt32());Assert.Empty(store.List<AuditOrigin>("auditOrigin").Items);var next=NativeWorkflow.Database() with{Source=NativeWorkflow.Database().Source with{Revision="2"}};NativeWorkflow.Publish(current,actor,next,1,1);var active=store.Read<DefinitionVersion>("active","db")!;using var json=System.Text.Json.JsonDocument.Parse(File.ReadAllText(Path.Combine(root,active.StoragePath,"manifest.json")));Assert.Equal(System.Text.Json.JsonValueKind.Null,json.RootElement.GetProperty("metadataConsumer").ValueKind);Assert.Empty(store.List<AuditOrigin>("auditOrigin").Items);Assert.True(Directory.Exists(root+"-backup"));
    }
    [Fact]public async Task AbruptTerminationAfterTheRealUpdateRecoversBothRowsAndPendingAudit(){
        var root=Root();var start=new System.Diagnostics.ProcessStartInfo("dotnet"){UseShellExecute=false,CreateNoWindow=true,WindowStyle=System.Diagnostics.ProcessWindowStyle.Hidden,RedirectStandardOutput=true,RedirectStandardError=true};foreach(var argument in new[]{typeof(CrashProbe).Assembly.Location,"--native-update-audit-probe",root}){start.ArgumentList.Add(argument);}using var child=System.Diagnostics.Process.Start(start)!;var created=child.StartTime.ToUniversalTime();using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(60));
        try{var stdout=child.StandardOutput.ReadToEndAsync(timeout.Token);var stderr=child.StandardError.ReadToEndAsync(timeout.Token);Assert.True(child.WaitForExit(60000));Assert.Equal(137,child.ExitCode);Assert.Empty(await stderr);var receipt=System.Text.Json.JsonSerializer.Deserialize<System.Text.Json.JsonElement>(await stdout);Assert.Equal(child.Id,receipt.GetProperty("Pid").GetInt32());Assert.Equal(created,receipt.GetProperty("Created").GetDateTime());if(OperatingSystem.IsWindows()||OperatingSystem.IsLinux()){using var current=System.Diagnostics.Process.GetCurrentProcess();Assert.Equal(current.ProcessorAffinity.ToInt64(),receipt.GetProperty("Affinity").GetInt64());}}
        finally{if(!child.HasExited){child.Kill(entireProcessTree:true);Assert.True(child.WaitForExit(60000));}}
        using var store=new ManagementStore(root);Assert.Empty(store.AuditEvents(new(Action:AuditAction.DataChange)).Items);using var service=new Seamless.Management.Server.ManagementService(store);var user=Login(service);Assert.Equal(1,Assert.Single(service.Execute(user,Request("count"),CancellationToken.None)).Value.GetInt32());await Until(()=>store.AuditEvents(new(Action:AuditAction.DataChange)).Items.Length==1);Assert.Equal("Committed",Assert.Single(store.AuditEvents(new(Action:AuditAction.DataChange)).Items).ResultCode);
    }
    internal static int RunStopProbe(string root){
        using var store=ManagementStore.Initialize(root,"admin","TestPassword-123");using var service=new Seamless.Management.Server.ManagementService(store){AuditDeliveryPaused=true};var user=Login(service);NativeWorkflow.Publish(service,user,NativeWorkflow.Database());NativeWorkflow.Publish(service,user,Update());NativeWorkflow.Publish(service,user,Count());_=service.Execute(user,Request("insert"),CancellationToken.None).ToArray();Assert.Empty(store.AuditEvents(new(Action:AuditAction.DataChange)).Items);using var process=System.Diagnostics.Process.GetCurrentProcess();long? affinity=null;if(OperatingSystem.IsWindows()||OperatingSystem.IsLinux()){affinity=process.ProcessorAffinity.ToInt64();}Console.WriteLine(System.Text.Json.JsonSerializer.Serialize(new{Pid=process.Id,Created=process.StartTime.ToUniversalTime(),Affinity=affinity}));Console.Out.Flush();Environment.Exit(137);return 3;
    }
}
